import{_ as s,o as a,c as n,ag as t}from"./chunks/framework.8tqBsFWt.js";const h=JSON.parse('{"title":"Formula Rules","description":"","frontmatter":{},"headers":[],"relativePath":"reference/reporting/formula-rules.md","filePath":"reference/reporting/formula-rules.md"}'),r={name:"reference/reporting/formula-rules.md"};function i(o,e,l,p,c,d){return a(),n("div",null,[...e[0]||(e[0]=[t(`<h1 id="formula-rules" tabindex="-1">Formula Rules <a class="header-anchor" href="#formula-rules" aria-label="Permalink to &quot;Formula Rules&quot;">​</a></h1><p>Critical rules for writing Google Sheets formulas in the reporting spreadsheet. These are derived from confirmed failures and are non-negotiable.</p><hr><h2 id="the-golden-pattern" tabindex="-1">The golden pattern <a class="header-anchor" href="#the-golden-pattern" aria-label="Permalink to &quot;The golden pattern&quot;">​</a></h2><p>Every dashboard formula should follow this structure:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=IFERROR(</span></span>
<span class="line"><span>  LET(</span></span>
<span class="line"><span>    base, FILTER(</span></span>
<span class="line"><span>      HSTACK(sheet!col_A, sheet!col_B, sheet!col_C),   ← inline sheet refs</span></span>
<span class="line"><span>      (sheet!status_col=&quot;active&quot;)*(sheet!cat_col=&quot;x&quot;)   ← inline condition</span></span>
<span class="line"><span>    ),</span></span>
<span class="line"><span>    f_x, CHOOSECOLS(base, 1),    ← split filtered result into named cols</span></span>
<span class="line"><span>    f_y, CHOOSECOLS(base, 2),</span></span>
<span class="line"><span>    ext, &#39;Other Sheet&#39;!A2:C,     ← pre-load cross-sheet ranges for LAMBDA</span></span>
<span class="line"><span>    computed, MAP(f_x, LAMBDA(v, SUMIF(ext, v, ...))),  ← MAP for element-wise ops</span></span>
<span class="line"><span>    SORT(HSTACK(f_x, f_y, computed), sort_col, FALSE)</span></span>
<span class="line"><span>  ),</span></span>
<span class="line"><span>  {&quot;No data&quot;,&quot;&quot;,&quot;&quot;}</span></span>
<span class="line"><span>)</span></span></code></pre></div><p>Key principles:</p><ul><li>FILTER condition <strong>inline</strong> — never in a LET variable</li><li>FILTER once, CHOOSECOLS to split</li><li>Pre-load cross-sheet ranges as LET variables before any LAMBDA</li><li>MAP/LAMBDA for computed columns</li><li>IFERROR wraps the entire LET</li></ul><hr><h2 id="rule-1-never-compare-a-let-range-variable-with" tabindex="-1">Rule 1: Never compare a LET range variable with <code>=</code> <a class="header-anchor" href="#rule-1-never-compare-a-let-range-variable-with" aria-label="Permalink to &quot;Rule 1: Never compare a LET range variable with \`=\`&quot;">​</a></h2><p><strong>Wrong:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>LET(</span></span>
<span class="line"><span>  p_status, &#39;02. Projects&#39;!F2:F,</span></span>
<span class="line"><span>  filtered, FILTER(data, p_status = &quot;active&quot;)  ← BROKEN</span></span>
<span class="line"><span>)</span></span></code></pre></div><p><strong>Why it breaks</strong>: A LET variable holding a sheet range evaluates as a scalar (first cell only) when compared with <code>=</code>. This silently collapses 999 rows to 1 row, causing &quot;FILTER has mismatched range sizes&quot; errors.</p><p><strong>Right:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>FILTER(data, &#39;02. Projects&#39;!F2:F = &quot;active&quot;)  ← compare sheet ref directly</span></span></code></pre></div><hr><h2 id="rule-2-never-use-arrayformula-inside-let" tabindex="-1">Rule 2: Never use ARRAYFORMULA inside LET <a class="header-anchor" href="#rule-2-never-use-arrayformula-inside-let" aria-label="Permalink to &quot;Rule 2: Never use ARRAYFORMULA inside LET&quot;">​</a></h2><p>ARRAYFORMULA is an evaluation-mode modifier. It does not expand correctly within LET&#39;s variable scoping.</p><p><strong>Wrong:</strong> <code>ARRAYFORMULA(SUMIF(...))</code> inside a <code>LET</code> block</p><p><strong>Right:</strong> Use <code>MAP(array, LAMBDA(v, SUMIF(...)))</code> instead.</p><hr><h2 id="rule-3-never-put-cross-sheet-references-inside-lambda" tabindex="-1">Rule 3: Never put cross-sheet references inside LAMBDA <a class="header-anchor" href="#rule-3-never-put-cross-sheet-references-inside-lambda" aria-label="Permalink to &quot;Rule 3: Never put cross-sheet references inside LAMBDA&quot;">​</a></h2><p>LAMBDA creates its own evaluation scope and cannot resolve <code>&#39;Sheet Name&#39;!range</code> references.</p><p><strong>Wrong:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>MAP(ids, LAMBDA(id,</span></span>
<span class="line"><span>  SUMIF(&#39;01. Time Entries&#39;!E2:E, id, &#39;01. Time Entries&#39;!G2:G)  ← BROKEN</span></span>
<span class="line"><span>))</span></span></code></pre></div><p><strong>Right:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>LET(</span></span>
<span class="line"><span>  te_proj, &#39;01. Time Entries&#39;!E2:E,   ← pre-load BEFORE the LAMBDA</span></span>
<span class="line"><span>  te_hrs,  &#39;01. Time Entries&#39;!G2:G,</span></span>
<span class="line"><span>  result, MAP(ids, LAMBDA(id, SUMIF(te_proj, id, te_hrs)))  ← use LET vars</span></span>
<span class="line"><span>)</span></span></code></pre></div><hr><h2 id="rule-4-sumif-and-vlookup-return-scalars-inside-let" tabindex="-1">Rule 4: SUMIF and VLOOKUP return scalars inside LET <a class="header-anchor" href="#rule-4-sumif-and-vlookup-return-scalars-inside-let" aria-label="Permalink to &quot;Rule 4: SUMIF and VLOOKUP return scalars inside LET&quot;">​</a></h2><p>Without ARRAYFORMULA (and you can&#39;t use that — see Rule 2), SUMIF and VLOOKUP return a scalar. Wrap them in <code>MAP</code> to iterate:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>totals, MAP(project_ids, LAMBDA(pid,</span></span>
<span class="line"><span>  SUMIF(te_project_col, pid, te_hours_col)</span></span>
<span class="line"><span>))</span></span></code></pre></div><hr><h2 id="rule-5-computed-arrays-vs-raw-range-references" tabindex="-1">Rule 5: Computed arrays vs raw range references <a class="header-anchor" href="#rule-5-computed-arrays-vs-raw-range-references" aria-label="Permalink to &quot;Rule 5: Computed arrays vs raw range references&quot;">​</a></h2><ul><li><strong>Computed array</strong> (result of FILTER/CHOOSECOLS/MAP): broadcasts correctly in <code>=</code> comparisons. Using it in SUMPRODUCT conditions inside MAP works: <code>SUMPRODUCT((f_pm=pid)*1)</code>.</li><li><strong>Raw range reference</strong> (<code>&#39;Sheet&#39;!A2:A</code>): does NOT broadcast correctly. Never store in LET and compare.</li></ul><hr><h2 id="rule-6-importrange-ghost-rows" tabindex="-1">Rule 6: IMPORTRANGE ghost rows <a class="header-anchor" href="#rule-6-importrange-ghost-rows" aria-label="Permalink to &quot;Rule 6: IMPORTRANGE ghost rows&quot;">​</a></h2><p>IMPORTRANGE on an empty source table often leaves a phantom row that passes <code>&lt;&gt;&quot;&quot;</code> checks. Guard against this:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=IF(SUM(te_hours)=0, {&quot;No data&quot;,&quot;&quot;,&quot;&quot;}, LET(...))</span></span></code></pre></div><p>Or use <code>ISNUMBER(col)*(col&gt;0)</code> as the filter condition.</p><hr><h2 id="rule-7-query-string-matching-is-case-sensitive" tabindex="-1">Rule 7: QUERY string matching is case-sensitive <a class="header-anchor" href="#rule-7-query-string-matching-is-case-sensitive" aria-label="Permalink to &quot;Rule 7: QUERY string matching is case-sensitive&quot;">​</a></h2><p>FILTER <code>=</code> is case-insensitive. QUERY <code>WHERE</code> is case-sensitive.</p><ul><li><code>22. Projects Master</code> uses <code>&quot;Active&quot;</code> (capital A)</li><li><code>02. Projects</code> uses <code>&quot;active&quot;</code> (lowercase)</li><li>In QUERY: <code>WHERE G = &#39;Active&#39;</code> — use capital A</li></ul><hr><h2 id="status-threshold-reference" tabindex="-1">Status threshold reference <a class="header-anchor" href="#status-threshold-reference" aria-label="Permalink to &quot;Status threshold reference&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Health status:</span></span>
<span class="line"><span>  pct_used &gt;= 1.0   → Over budget (🚨)</span></span>
<span class="line"><span>  pct_used &gt;= 0.80  → Warning (⚠️)</span></span>
<span class="line"><span>  pct_used &lt;  0.80  → Healthy (✅)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Retainer burn rate:</span></span>
<span class="line"><span>  projected_pct &gt; 1.50  → Critical overpace</span></span>
<span class="line"><span>  projected_pct &gt; 1.10  → Warning overpace</span></span>
<span class="line"><span>  projected_pct &gt;= 0.90 → On track</span></span>
<span class="line"><span>  projected_pct &gt;= 0.50 → Warning underpace</span></span>
<span class="line"><span>  projected_pct &lt;  0.50 → Critical underpace</span></span></code></pre></div><hr><h2 id="quoting-rule-for-sheet-names" tabindex="-1">Quoting rule for sheet names <a class="header-anchor" href="#quoting-rule-for-sheet-names" aria-label="Permalink to &quot;Quoting rule for sheet names&quot;">​</a></h2><p>Only tab names with special characters need single quotes in formula strings:</p><ul><li><code>=IMPORT_DB(&quot;01. Time Entries!A:H&quot;)</code> — no quotes needed</li><li><code>=IMPORT_DB(&quot;&#39;22. Projects Master&#39;!A:P&quot;)</code> — quotes required (space in name)</li></ul><p>When referencing hidden mirror sheets directly in formulas, the same rule applies:</p><ul><li><code>&#39;01. Time Entries&#39;!A2:A</code> — quotes required for all tab names with spaces or dots in cross-sheet references</li></ul><hr><h2 id="debugging-checklist" tabindex="-1">Debugging checklist <a class="header-anchor" href="#debugging-checklist" aria-label="Permalink to &quot;Debugging checklist&quot;">​</a></h2><p>If a formula returns unexpected results:</p><ol><li><strong>FILTER mismatch</strong> — are you comparing a LET range variable? Move the condition inline.</li><li><strong>Single value returned</strong> — is a SUMIF/VLOOKUP not inside MAP? Wrap it.</li><li><strong>LAMBDA error</strong> — is a cross-sheet reference inside LAMBDA? Pre-load it as a LET variable.</li><li><strong>Ghost row from IMPORTRANGE</strong> — guard with <code>IF(SUM(col)=0, fallback, LET(...))</code>.</li><li><strong>QUERY returns nothing</strong> — check case sensitivity; use capital A for Active status.</li></ol>`,56)])])}const g=s(r,[["render",i]]);export{h as __pageData,g as default};
